options.helpers:
const valid = value => typeof value === 'number' && Number.isFinite(value);
const memory = value => !valid(value) ? 'Unknown' : value >= 1073741824 ? (value / 1073741824).toFixed(1) + ' GiB' : (value / 1048576).toFixed(0) + ' MiB';
context.handlebars.registerHelper('containerName', value => String(value || 'Unknown').replace(/^.+-prod[-_]/, ''));
context.handlebars.registerHelper('memory', memory);
context.handlebars.registerHelper('memoryLimit', value => value === 0 ? 'No cap' : memory(value));
context.handlebars.registerHelper('percentage', value => valid(value) ? value.toFixed(1) + '%' : 'N/A');
context.handlebars.registerHelper('pressure', value => !valid(value) ? 'load-unknown' : value >= 90 ? 'load-critical' : value >= 80 ? 'load-warning' : 'load-normal');
